def add(a, b):
    return a + b

def subtract(a, b):
    # BUG: wrong order
    return b - a

def multiply(a, b):
    return a * b

def divide(a, b):
    if b == 0:
        raise ValueError("division by zero")
    # BUG: integer division instead of float
    return a // b

